// UIL 2006 - Regional Programming Contest
//
// count.java
//
// The purpose of this problem is to test contestant
// ability to read input from a file and use arrays
// (or more complicated structures)
//

import java.io.*;
import java.util.*;


public class count {
   
   public static final int ASCII_a = 97;

   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("count.in") );

      int charCount[] = new int[26];

      int numLines = infile.nextInt();
      infile.nextLine();

      // zero character counts
      for (int i=0; i<26; i++) {
         charCount[i] = 0;
      }

      // count the letters
      for (int l=0; l<numLines; l++) {

         // convert next line to lower case
         String line = new String( infile.nextLine().toLowerCase() );

         for (int i=0; i<line.length(); i++) {

            if ( Character.isLetter( line.charAt(i) ) ) {
               charCount[(line.charAt(i))-ASCII_a]++;
            }

         }

      }

      // output the results
      for (int i=0; i<26; i++) {
         System.out.println( ((char)(ASCII_a+i)) + " " + charCount[i] );
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// dinner.java
//
// The purpose of this problem is to test contestant
// ability to perform a simulation.
//

import java.io.*;
import java.util.*;

public class dinner {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("dinner.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {

         int numDogs    = infile.nextInt();
         int numRabbits = infile.nextInt();
         int numCarrots = infile.nextInt();
         int numDays    = infile.nextInt();
         infile.nextLine();

         for (int day=0; day<numDays; day++) {

            // rabbits eat carrots
            numCarrots -= numRabbits*3;
            if (numCarrots < 0) {
               numRabbits -= (Math.abs(numCarrots) + 2) / 3;
               numCarrots = 0;
            }

            // dogs eat rabbits
            numRabbits -= numDogs*2;
            if (numRabbits < 0) {
               numDogs -= (Math.abs(numRabbits) + 1) / 2;
               numRabbits = 0;
            }
         }

         System.out.println(numDogs + " " + numRabbits + " " + numCarrots);

      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// distance.java
//
// The purpose of this problem is to test: 
//    choosing the best of several alternatives
//    reading formatted input
//    writing formatted output
//

import java.io.*;
import java.util.*;

class plan {
   String name;
   int minutes;
   float monthly;
   float additional;
   float cost;
}

public class distance {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("distance.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
 
         int numPlans   = infile.nextInt();
         int numCallers = infile.nextInt();
         infile.nextLine();

         // print the header
         System.out.println("Data set #" + (i+1));

         // read in the plans
         plan planArray[] = new plan[numPlans];
         for (int p=0; p<numPlans; p++) {
            planArray[p] = new plan();

            infile.next(); // throw away token "Plan"
            planArray[p].name       = infile.next();
            planArray[p].minutes    = infile.nextInt();
            planArray[p].monthly    = 
               (new Float(infile.next().substring(1))).floatValue();
            planArray[p].additional = 
               (new Float(infile.next().substring(1))).floatValue();
            infile.nextLine();
         }

         // process the callers
         for (int c=0; c<numCallers; c++) {
            String caller = infile.next();
            int minutes   = infile.nextInt();
            infile.nextLine();

            //calculate the cost of each plan
            plan lowcostplan = null;
            for (int p=0; p<numPlans; p++) {
               plan myplan = planArray[p];

               int overage = minutes - myplan.minutes;
               if (overage < 0) { overage = 0; }

               myplan.cost = myplan.monthly + 
                            (myplan.additional * (float)overage);
               
               if (lowcostplan == null ||
                  lowcostplan.cost > myplan.cost)
               {
                  lowcostplan = myplan;
               }
            }

            //output the cheapest plan info
            System.out.printf(
                  "%s should choose plan %s for $%.2f per month.\n",
                  caller, lowcostplan.name, lowcostplan.cost ); 
         }
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// look.java
//
// The purpose of this problem is to test contestant
// ability to perform non-trivial mathematical manipulations.
//
// Note: This is, by far, the hardest regional problem in
// this year's set.  It is doable, but should certainly be
// done last.  Fortunately, the trickiest component is
// figuring out the formulas needed.  If a team can have
// one member doing all the calculations for this problem
// while other solutions are being coded, this problem
// could be done in a contest setting.
//
// However, there are also quite a large number of
// special cases, so there is not only a large debugging
// period necessary for solving this problem, but as
// long as the master data is thorough, it is likely that
// the master data will test boundary conditions that
// were not thought of by the solution writer.
//

import java.io.*;
import java.util.*;

public class look {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("look.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
         double lx      = infile.nextDouble();
         double ly      = infile.nextDouble();
         double radius  = infile.nextDouble();
         double bx      = infile.nextDouble();
         double by      = infile.nextDouble();
         double hdeg    = infile.nextDouble();  // heading in degrees
         double hrad    = Math.toRadians(hdeg); // heading in radians
         infile.nextLine();

         // formula for a circle is (x-lx)^2 + (y-ly)^2 = r^2
         //    luckily, we already know lx, ly, and r
         // formula for a line is y = mx + b
         //    we need to calculate m and b
         //    m is easiest, since slope is the tangent of the angle
         //    however, tangent is undefined at 90 * 270 degrees

         if (hdeg == 90 || hdeg == 270) {
            // the formula for the boat's line is x = bx
            // we will never hit shore
            // (bx-lx)^2 + (y-ly)^2 = r^2
            // (y-ly)^2 = r^2 - (bx-lx)^2
            // y-ly = +/- sqrt(r^2 - (bx-lx)^2)
            // y = +/- sqrt(r^2 - (bx-lx)^2) + ly
            double desc = Math.pow(radius,2.0) - Math.pow(bx-lx,2.0);
            if (desc < 0) {    // imaginary, never see the lighthouse
               System.out.println("Lost at sea");
            }
            else {
               double y1 = Math.sqrt(desc) + ly;
               double y2 = -Math.sqrt(desc) + ly;
               if (  (hdeg == 90  && ((y1 >= by) || (y2 >= by))) 
                     ||
                     (hdeg == 270 && ((y1 <= by) || (y2 <= by))) ) {
                  System.out.println("Saved by the lighthouse");
               }
               else {
                  System.out.println("Lost at sea");
               }
            }
         }
         else {
            double m = Math.tan(hrad);
            double b = by - (m * bx);
            // Ok, so we know all of y = mx + b
            // now, substitute mx + b for y in the circle forumla:
            //    (x-lx)^2 + (mx+b-ly)^2 = r^2
            //    x^2 - 2xlx + lx^2 + m^2x^2 + 2mx(b-ly) + (b-ly)^2 = r^2
            //    (m^2 + 1)x^2 + (2lx + 2m(b-ly))x + (lx^2 + (b-ly)^2 - r^2) = 0
            // now use the quadratic formula to solve:
            //    Ax^2 + Bx + C = 0
            //    x = (-B +/-SQRT(B^2 - 4AC)) / 2A
            //    descrimiate = (B^2 - 4AC)
            double A = Math.pow(m,2.0) + 1;
            double B = (2 * m * (b - ly)) - (2 * lx);
            double C = 
               Math.pow(lx,2.0) + Math.pow(b-ly,2.0) - Math.pow(radius, 2.0);
            double desc = Math.pow(B,2.0) - (4 * A * C);
            if (desc < 0) {
               // solutions are imaginary, the boat never sees the light
               // we know he'll hit shore if 90 < heading < 270
               if ( (90 < hdeg) && (hdeg < 270) ) {
                  System.out.println("Look out!");
               } 
               else {
                  System.out.println("Lost at sea");
               }
            }
            else {
               // the boat might see the light, as long as he's headed
               // toward it instead of away.
               // we have to finish calculating the intersection points
               double x1 = (-B + Math.sqrt(desc)) / (2*A);
               double x2 = (-B - Math.sqrt(desc)) / (2*A);
               double y1 = m*x1 + b;
               double y2 = m*x2 + b;

               // now figure out if (x1,y1) or (x2,y2) is in front of the boat
               if (hdeg > 90 && hdeg < 270) { // going west
                  if ((x1 > 0 && x1 < bx) ||  // cross before hit land
                      (x2 > 0 && x2 < bx) ||  // cross before hit land
                      (x1 < bx && x2 > bx) || // already in the light
                      (x1 > bx && x2 < bx)) { // already in the light
                     System.out.println("Saved by the lighthouse");
                  }
                  else {
                     System.out.println("Look out!");
                  }
               }
               else { // going east
                  if ((x1 > bx) ||            // see light eventually
                      (x2 > bx) ||            // see light eventually
                      (x1 < bx && x2 > bx) || // already in the light
                      (x1 > bx && x2 < bx)) { // already in the light
                     System.out.println("Saved by the lighthouse");
                  }
                  else {
                     System.out.println("Lost at sea");
                  }
               }
            }
         }
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// maze.java
//
// The purpose of this problem is to test contestant
// ability to use two-dimensional arrays and perform
// optimal path finding.
//

import java.io.*;
import java.util.*;

class cell {

   public cell () {
      type = '.';
      distance = 1000;
      closestcell = null;
   }

   char type;
   int distance;
   cell closestcell;
}

public class maze {

   private static final int UP    = 0;
   private static final int DOWN  = 1;
   private static final int LEFT  = 2;
   private static final int RIGHT = 3;
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("maze.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
         boolean foundatty = false;
         cell startcell = null;
         cell endcell   = null;
         int width  = infile.nextInt();
         int height = infile.nextInt();
         infile.nextLine();

         // create an empty maze
         cell[][]  Maze = new cell[height][width];

         // populate it from the intput file
         for (int h=0; h<height; h++) {
            // read next line of the maze
            String line = infile.nextLine();
            for (int w=0; w<width; w++) {
               Maze[h][w] = new cell();
               Maze[h][w].type = line.charAt(w);
               if (line.charAt(w) == '@') {
                  if (!foundatty) {
                     foundatty = true;
                     startcell = Maze[h][w];
                     startcell.distance = 0;
                  }
                  else {
                     endcell = Maze[h][w];
                     endcell.type = '.';
                  }
               }
            }
         }

         // iterate over the maze until there are no more changes
         // note that this could be done recursively, but I find that
         // the algorithm is no simpler in that case, which defeats the
         // purpose.
         boolean changed = true; // indicates if we made a change on last pass
         while (changed) {
            changed = false;
            for (int h=0; h<height; h++) {
               for (int w=0; w<width; w++) {
                  cell thiscell = Maze[h][w];

                  cell adjacent[] = { null, null, null, null } ;
                  if (h > 0)        { adjacent[UP]    = Maze[h-1][w]; }
                  if (h < height-1) { adjacent[DOWN]  = Maze[h+1][w]; }
                  if (w > 0)        { adjacent[LEFT]  = Maze[h][w-1]; }
                  if (w < width-1)  { adjacent[RIGHT] = Maze[h][w+1]; }

                  // the only thing we process is blank floor
                  if (thiscell.type == '.') {
                     // look for adjacent cells with distance at least 2 less
                     for (int a=0; a<4; a++) {
                        if (adjacent[a] != null  && 
                            adjacent[a].distance < (thiscell.distance - 1) ) {
                           // we found a new shortest path to here
                           thiscell.distance    = adjacent[a].distance + 1;
                           thiscell.closestcell = adjacent[a];
                           changed = true;
                        }
                     }
                  }
               }
            }
         }

         // fill the shortest path with '@' 
         cell mycell = endcell;
         while (mycell != startcell) { // yep, we do this backward
            mycell.type = '@';
            mycell = mycell.closestcell;
         }

         // display results
         for (int h=0; h<height; h++) {
            for (int w=0; w<width; w++) {
               System.out.printf("%c", Maze[h][w].type);
            }
            System.out.println("");
         }
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// notes.java
//
// The purpose of this problem is to test contestant
// ability to simulate 'infection' of a group using
// a mathematical formula for group contact.
//

import java.io.*;
import java.util.*;

public class notes {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("notes.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
         int source = infile.nextInt();
         int target = infile.nextInt();
         int time   = 0;

         // only the source person is infected at the start
         boolean[] isInfected = new boolean[101]; // for unit indexing
         isInfected[source] = true;

         // process divisors until target is infected
         while (!isInfected[target]) {
            int divisor = infile.nextInt();

            // spread the infection
            // there are <divisor> groups, made up of:
            //   group 0: 0,   d,   2d,   3d, ...
            //   group 1: 1, 1+d, 1+2d, 1+3d, ...
            //   group x: x, x+d, x+2d, x+3d, ...
            for (int group=0; group<divisor; group++) {
               boolean groupInfected = false;
               for (int member = group; member <= 100; member += divisor) {
                  if (isInfected[member]) {
                     groupInfected = true;
                     break;
                  }
               }
               if (groupInfected) {
                  for (int member = group; member <= 100; member += divisor) {
                     isInfected[member] = true;
                  }
               }
            }

            if (isInfected[target]) { break; }
            time += 5;
         }
         infile.nextLine();

         System.out.println(time + " minutes");
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// ship.java
//
// The purpose of this problem is to test contestant
// ability to perform a simulation of a game when
// given the moves.
//

import java.io.*;
import java.util.*;

public class ship {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("ship.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
         String[] board = new String[10];

         System.out.println ("Data Set #" + (i+1));

         // read in game board
         for (int j=0; j<10; j++) {
            board[j] = infile.nextLine();
         }

         // prep counters
         int C_hitsleft = 5;
         int B_hitsleft = 4;
         int D_hitsleft = 3;
         int S_hitsleft = 3;
         int P_hitsleft = 2;

         // how many shots?
         int numShots = infile.nextInt();
         infile.nextLine();

         // process shots
         for (int s=0; s<numShots; s++) {
            String shot = infile.next();
            int row = ((int)shot.charAt(0)) - 65;
            int col = Integer.parseInt(shot.substring(1)) - 1;
            System.out.print(shot + " ");

            switch (board[row].charAt(col)) {
               case '.':
                  System.out.println("miss");
                  break;
               case 'C':
                  --C_hitsleft;
                  if (C_hitsleft <= 0) 
                     { System.out.println("sank my carrier!"); }
                  else 
                     { System.out.println("hit!"); }
                  break;
               case 'B':
                  --B_hitsleft;
                  if (B_hitsleft <= 0) 
                     { System.out.println("sank my battleship!"); }
                  else 
                     { System.out.println("hit!"); }
                  break;
               case 'D':
                  --D_hitsleft;
                  if (D_hitsleft <= 0) 
                     { System.out.println("sank my destroyer!"); }
                  else 
                     { System.out.println("hit!"); }
                  break;
               case 'S':
                  --S_hitsleft;
                  if (S_hitsleft <= 0) 
                     { System.out.println("sank my submarine!"); }
                  else 
                     { System.out.println("hit!"); }
                  break;
               case 'P':
                  --P_hitsleft;
                  if (P_hitsleft <= 0) 
                     { System.out.println("sank my patrol boat!"); }
                  else 
                     { System.out.println("hit!"); }
                  break;
               default:
                  System.err.println("Bad entry!!!");
            }
         }
         infile.nextLine();
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// skyline.java
//
// The purpose of this problem is to test contestant
// ability to manipulate 3-dimensional arrays.
//

import java.io.*;
import java.util.*;

public class skyline {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("skyline.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
         int maxheight = 0;
         int size = infile.nextInt();
         infile.nextLine();

         // downtown[height][south][east]
         boolean[][][] downtown = new boolean[9][size][size];

         // recreate a 3D logical representation of downtown
         for (int s=0; s<size; s++) {
            String line = infile.nextLine();
            for (int e=0; e<size; e++) {
               int height = ((int)line.charAt(e)) - 48;
               for (int h=0; h<height; h++) {
                  downtown[h][s][e] = true;
               }
               if (height > maxheight) { maxheight = height; }
            }
         }

         // now print the view from the west
         System.out.println("Data Set #" + (i+1));
         for (int h = maxheight - 1; h>=0; h--) {
            for (int s = 0; s < size; s++) {
               int e;
               for (e = 0; ; e++) {
                  if (e == size) {
                     System.out.print(".");
                     break;
                  }
                  if (downtown[h][s][e]) {
                     System.out.print(e+1);
                     break;
                  }
               }
            }
            System.out.println("");
         }
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// sort.java
//
// The purpose of this problem is to test contestant
// ability to sort data using non-trivial comparison
// operations.
//

import java.io.*;
import java.util.*;

class myword {

   String real_word;
   String rev_word;

   public myword (String input_word) {
      real_word = new String(input_word);

      char[] temp1 = real_word.toCharArray();
      char[] temp2 = new char[temp1.length];
      for (int i=0; i<temp1.length; i++) {
         temp2[i] = temp1[(temp1.length-i)-1];
      }

      rev_word = String.copyValueOf(temp2);
   }
}

public class sort {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("sort.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
         int numWords = infile.nextInt();
         infile.nextLine();

         myword[] words = new myword[numWords];
         for (int w=0; w<numWords; w++) {
            words[w] = new myword(infile.nextLine());
         }

         //bubble sort
         boolean changed = true;
         while (changed) {
            changed = false;
            for (int w=0; w<(numWords-1); w++) {
               if (words[w].rev_word.compareToIgnoreCase(words[w+1].rev_word) > 0) {
                  changed = true;
                  myword temp_word = words[w];
                  words[w] = words[w+1];
                  words[w+1] = temp_word;
               }
            }
         }

         //display
         System.out.println("Data Set #" + (i+1));
         for (int w=0; w<numWords; w++) {
            System.out.println(words[w].real_word);
         }
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// triage.java
//
// The purpose of this problem is to test contestant
// ability to perform a simulation using priority queues.
// Whether the Java ADT for a priority queue is directly
// used does not matter.  Solutions will have to
// determine which patient in the waiting room has the
// highest priority in some fashion, and that counts.
//

import java.io.*;
import java.util.*;

class patient implements Comparable<patient> {
   int arrived;
   int priority;
   int duration;
   public patient (int a, int p, int d) {
      arrived  = a;
      priority = p;
      duration = d;
   }
   public int compareTo (patient p) {
      if (this.priority != p.priority) {
         return (this.priority - p.priority);
      }
      return (this.duration - p.duration);
   }
}

public class triage {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("triage.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {
         int treatmentEndTime = 0;
         int numPatients = infile.nextInt();
         infile.nextLine();

         PriorityQueue<patient> waiting = new PriorityQueue<patient>();
         LinkedList<patient> arrivals = new LinkedList<patient>();
         patient beingTreated = null;
         for (int p=0; p<numPatients; p++) {
            arrivals.add(new patient(infile.nextInt(), 
                                     infile.nextInt(), 
                                     infile.nextInt()));
            infile.nextLine();
         }

         // get everyone treated
         int time=0;
         while ((waiting.size() + arrivals.size()) > 0) {

            // we only get here when nobody is being treated
            // the first thing to do is check the waiting room
            // GET THE HIGHEST PRIORITY PERSION TO THE OR
            if (waiting.size() == 0) {

               // have everyone arriving at the 
               // next tick go to the waiting room
               time = arrivals.peek().arrived;
               while (arrivals.size() > 0 &&
                      arrivals.peek().arrived == time) {
                  waiting.add(arrivals.poll());
               }
            }

            // now we know someone is in the waiting room and
            // nobody is being treated, so let's treat someone!
            beingTreated = waiting.poll();
            treatmentEndTime = time + beingTreated.duration;

            // now, we need to keep processing arrivals into the
            // waiting room until the current treatment is complete
            // or until a higher priority case arrives.
            while (true) {
               if (arrivals.size() == 0 ||
                   arrivals.peek().arrived >= treatmentEndTime) {
                  time = treatmentEndTime;
                  beingTreated = null; 
                  break;
               }
               time = arrivals.peek().arrived;
               while (arrivals.size() > 0 &&
                      arrivals.peek().arrived == time) {
                  waiting.add(arrivals.poll());
               }
               if (waiting.peek().priority < beingTreated.priority) {
                  waiting.add(beingTreated);
                  beingTreated = null;
                  break;
               }
            }

            // at this point, nobody is being treated, so it's
            // time to go back to the top of the loop.
         }

         // if we're here, then the treatmentEndTime has already
         // been calculated for the final patient.
         System.out.println(treatmentEndTime);
      }
   }
}

// UIL 2006 - Regional Programming Contest
//
// vowel.java
//
// The purpose of this problem is to test contestant
// ability to read input from a file and use conditional tests.
//

import java.io.*;
import java.util.*;

public class vowel {
   
   public static void main (String args[]) throws IOException {

      Scanner infile = new Scanner( new File("vowel.in") );

      int numDataSets = infile.nextInt();
      infile.nextLine();

      for (int i=0; i<numDataSets; i++) {

         String word = new String(infile.nextLine());
         String vORc;

         if (word.substring(0,1).matches("[aeiouAEIOU]")) {
            vORc = "vowel";
         }
         else {
            vORc = "consonant";
         }

         System.out.println(
                         "The word '" + word + "' begins with a " + vORc + ".");
      }
   }
